@namespace sv_f76244fc47744f4b9f9c001e6a02ae65.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image-placeholder">
        <span>@Product.Name</span>
    </div>
    <div class="product-info">
        <h5 class="product-name" title="@Product.Name">@Product.Name</h5>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" title="@($"{Product.Rating:F1} out of 5")">
            @RenderStars(Product.Rating)
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger">Out of Stock</span>
        }
        <button class="btn btn-primary btn-sm mt-2 add-to-cart-btn"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick() => await OnSelected.InvokeAsync(Product);

    private async Task HandleAddToCart() => await OnAddToCart.InvokeAsync(Product);

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

